<?php if(!defined("ABSPATH"))exit; require SENTINEL_PLUGIN_DIR."admin/views/partials/header.php"; if(!class_exists("Sentinel_WP_Recommendations"))require_once SENTINEL_PLUGIN_DIR."includes/modules/scanner/class-wp-recommendations.php"; $results=Sentinel_WP_Recommendations::run(); $summary=Sentinel_WP_Recommendations::summary(); $sc=array("pass"=>"#43a047","warn"=>"#f57c00","fail"=>"#e53935"); $si=array("pass"=>"&#10003;","warn"=>"&#9888;","fail"=>"&#10007;"); ?><div class="wrap sentinel-wrap"><div class="sentinel-page-header"><div class="sentinel-header-left"><span class="dashicons dashicons-yes-alt sentinel-header-icon"></span><h1><?php esc_html_e("Security Recommendations","wp-sentinel-security"); ?></h1></div></div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px;"><?php foreach(array(array("Score","{$summary["score"]}%","#1976d2"),array("Passed",$summary["pass"],"#43a047"),array("Warnings",$summary["warn"],"#f57c00"),array("Failed",$summary["fail"],"#e53935"))as$c):?><div class="sentinel-card" style="text-align:center;padding:20px;"><div style="font-size:2rem;font-weight:700;color:<?php echo esc_attr($c[2]);?>"><?php echo esc_html($c[1]);?></div><div style="color:#555;margin-top:4px;"><?php echo esc_html($c[0]);?></div></div><?php endforeach;?></div><div class="sentinel-card"><h2 style="margin-top:0;"><?php esc_html_e("Check Results","wp-sentinel-security");?></h2><table class="wp-list-table widefat fixed striped"><thead><tr><th>Status</th><th>Check</th><th>Details</th><th>Severity</th><th>Action</th></tr></thead><tbody><?php foreach($results as $r):$c2=$sc[$r["status"]]??"#888";$i=$si[$r["status"]]??"?";$sv=array("critical"=>"#e53935","high"=>"#f57c00","medium"=>"#1976d2","low"=>"#777");$c3=$sv[$r["severity"]]??"#888";?><tr><td style="text-align:center;font-size:1.2em;color:<?php echo esc_attr($c2);?>"><?php echo $i;?></td><td><strong><?php echo esc_html($r["title"]);?></strong></td><td style="color:#444;font-size:0.9em;"><?php echo esc_html($r["description"]);?></td><td><span style="background:<?php echo esc_attr($c3);?>;color:#fff;font-size:0.75em;padding:2px 6px;border-radius:4px;text-transform:capitalize;"><?php echo esc_html($r["severity"]);?></span></td><td><?php if("pass"!==$r["status"]&&!empty($r["fix_url"])):?><a href="<?php echo esc_url($r["fix_url"]);?>" class="button button-small" target="_blank">Fix</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
